use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr1 = input.as_array().unwrap();
    let arr2 = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut left = 0;
    let mut right = 0;

    while left < arr1.len() && right < arr2.len() {
        let key1 = arr1[left].as_i64().unwrap();
        let key2 = arr2[right].as_i64().unwrap();
        if key1 == key2 {
            result.push(Value::from((key1, arr1[left].as_i64().unwrap(), arr2[right].as_i64().unwrap())));
            left += 1;
            right += 1;
        } else if key1 < key2 {
            left += 1;
        } else {
            right += 1;
        }
    }

    Value::from(result)
}
